const STORE_KEY = "nakaya-portal-v5";
const todayStr = () => new Date().toDateString();
const weekKey = () => "w" + Math.floor((Date.now() / 86400000 + 4) / 7);
const hashStr = (s) => { let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; } return Math.abs(h); };
const makeCode = () => Array.from({ length: 6 }, () => "ABCDEFGHJKMNPQRSTUVWXYZ23456789"[Math.floor(Math.random() * 31)]).join("");

async function sGet(key, shared = false) { try { const r = await window.storage.get(key, shared); return r && r.value ? JSON.parse(r.value) : null; } catch (e) { return null; } }
async function sSet(key, val, shared = false) { try { await window.storage.set(key, JSON.stringify(val), shared); return true; } catch (e) { return false; } }

const daysAgoStr = (n) => new Date(Date.now() - n * 86400000).toDateString();

// ——— THE TIDE · shared world-state ———
const TIDE_KEY = "tide:state";
async function tideGet() {
  let t = await sGet(TIDE_KEY, true);
  const now = Date.now();
  if (!t) t = { level: 62, updated: now, acts: [] };
  const hours = (now - t.updated) / 3600000;
  if (hours > 0.5) { t.level = Math.min(95, t.level + hours * 0.02); t.updated = now; await sSet(TIDE_KEY, t, true); }
  return t;
}
async function tidePush(amount, label) {
  const t = await tideGet();
  t.level = Math.max(5, t.level - amount);
  t.updated = Date.now();
  t.acts = [...(t.acts || []), { l: label, ts: Date.now() }].slice(-80);
  await sSet(TIDE_KEY, t, true);
  return t;
}

