function collectFragments(ev, st) {
  return FRAG.filter(f => !(st.fragments || []).includes(f.id) && f.when(ev, st)).map(f => f.id);
}
function questionState(st, n) {
  const all = FRAG.filter(f => f.q === n);
  const got = all.filter(f => (st.fragments || []).includes(f.id));
  return { total: all.length, got: got.length, frags: got, done: got.length === all.length };
}

const DREAM_FALLBACK = (line) => `You are wading in shallow warm water under a sky the color of closed eyelids. Somewhere behind you, your own voice says "${line}" and the words leave your mouth as small pale fish. They swim ahead of you, unhurried, certain of the way. The river narrows between two stones that breathe. On the far bank a being you have met before stands very still, holding a lantern that is not lit, because nothing here is dark. It nods once, as if the fish had delivered something. You understand nothing and feel entirely understood. The water begins, very gently, to glow.`;


const FRESH = { tribe: {}, regionCounts: {}, lastPullDate: null, lastBeingId: null, connections: 0, memories: {}, anonId: null, lastSentWeek: null, kinCode: null, kinRole: null, displayName: "", deeds: {}, deedLog: [], myReflections: [], dreams: [], dreamOffering: null, inscribed: {}, onboarded: false, fragments: [], firstsSeen: {}, readFragCount: 0 };
async function loadState() { const s = await sGet(STORE_KEY); const st = s ? { ...FRESH, ...s } : { ...FRESH }; if (!st.anonId) st.anonId = makeCode() + makeCode(); return st; }

const regionCount = (state, name) => state.regionCounts?.[name] || 0;
const allRegionsComplete = (state) => REGIONS.every(r => regionCount(state, r.name) >= UNLOCK_AT);

// current position: highest region reached, where a region is "reached" once the one below it is complete
function currentRegionIdx(state) {
  let idx = 0;
  for (let i = 0; i < REGIONS.length - 1; i++) {
    if (regionCount(state, REGIONS[i].name) >= UNLOCK_AT) idx = i + 1; else break;
  }
  return idx;
}

const DIST_WEIGHT = [100, 30, 20, 10, 7, 5, 3];

function pickBeing(state) {
  // The Maw appears rarely, from anywhere
  if (Math.random() < 0.04) return BEINGS.find(b => b.id === "maw");
  // Mount Ịsa only when every region is complete
  if (allRegionsComplete(state) && Math.random() < 0.12) return BEINGS.find(b => b.id === "evarin");

  const here = currentRegionIdx(state);
  const pool = [];
  REGIONS.forEach((r, i) => {
    const d = Math.abs(i - here);
    const w = DIST_WEIGHT[Math.min(d, DIST_WEIGHT.length - 1)];
    const members = BEINGS.filter(b => b.region === r.name);
    if (members.length) pool.push({ region: r.name, weight: w, members });
  });
  const total = pool.reduce((s, p) => s + p.weight, 0);
  let roll = Math.random() * total;
  let chosen = pool[0];
  for (const p of pool) { roll -= p.weight; if (roll <= 0) { chosen = p; break; } }
  let members = chosen.members;
  if (members.length > 1) members = members.filter(b => b.id !== state.lastBeingId);
  return members[Math.floor(Math.random() * members.length)];
}

